import type { ColorTokens } from "@/registry/types/pdf-themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import { isValidElement } from "react";
import type { DependencyList, ReactNode } from "react";

import { professionalTheme } from "@/registry/themes/professional";

export type PdfcnTheme = typeof professionalTheme;

let serializedTheme = professionalTheme;

export interface PdfcnThemeProviderProps {
  theme?: PdfcnTheme;
  children: ReactNode;
}

const renderForSerializer = (
  children: ReactNode,
  theme: PdfcnTheme
): ReactNode => {
  serializedTheme = theme;

  if (!isValidElement(children) || typeof children.type !== "function") {
    return children;
  }

  return (children.type as (props: unknown) => ReactNode)(children.props);
};

export const PdfcnThemeProvider = ({
  theme,
  children,
}: PdfcnThemeProviderProps) =>
  renderForSerializer(children, theme ?? professionalTheme);

export const usePdfcnTheme = (): PdfcnTheme => serializedTheme;

export const useSafeMemo = <T,>(factory: () => T, _deps: DependencyList): T =>
  factory();

import type { AnchorHTMLAttributes, ImgHTMLAttributes, ReactNode } from "react";

export type Style = Record<string, unknown>;

export const StyleSheet = {
  create<T extends Record<string, Style>>(styles: T): T {
    return styles;
  },
};

type StyleInput = Style | Style[] | false | null | undefined;

export const flatten = (
  style?: StyleInput
): Record<string, unknown> | undefined => {
  if (!style) {
    return undefined;
  }
  if (Array.isArray(style)) {
    return Object.assign({}, ...style.filter(Boolean));
  }
  return style;
};

interface ViewProps {
  children?: ReactNode;
  style?: StyleInput;
  className?: string;
  wrap?: boolean;
  fixed?: boolean;
  break?: boolean;
  minPresenceAhead?: number;
}

export const View = ({ children, style, className, ...rest }: ViewProps) => {
  const {
    wrap,
    fixed,
    break: br,
    minPresenceAhead: _m,
    ...dom
  } = rest as ViewProps & Record<string, unknown>;
  const merged = {
    display: "flex",
    flexDirection: "column",
    ...flatten(style),
  };
  if (br) {
    Object.assign(merged, { breakBefore: "page" });
  }
  if (wrap === false) {
    Object.assign(merged, { breakInside: "avoid" });
  }
  if (fixed) {
    Object.assign(merged, { position: "fixed" });
  }
  return (
    <div
      className={className}
      style={merged as React.CSSProperties}
      {...(dom as object)}
    >
      {children}
    </div>
  );
};

interface TextProps {
  children?: ReactNode;
  style?: StyleInput;
  className?: string;
  render?: (info: { pageNumber: number; totalPages: number }) => ReactNode;
  fixed?: boolean;
  href?: string;
  src?: string;
}

export const Text = ({
  children,
  style,
  className,
  render: _render,
  href,
  src,
  ...rest
}: TextProps) => {
  const merged = flatten(style) as React.CSSProperties | undefined;
  const link = href ?? src;
  if (link) {
    return (
      <a href={link} className={className} style={merged} {...(rest as object)}>
        {children}
      </a>
    );
  }
  return (
    <span className={className} style={merged} {...(rest as object)}>
      {children}
    </span>
  );
};

export const Image = ({
  src,
  style,
  ...rest
}: {
  src: string | { uri: string };
  style?: StyleInput;
} & Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "style">) => {
  const resolved = typeof src === "string" ? src : src.uri;
  return (
    // eslint-disable-next-line eslint(nextjs/no-img-element) -- PDF primitive, not Next.js page
    <img
      src={resolved}
      style={flatten(style) as React.CSSProperties}
      alt=""
      {...rest}
    />
  );
};

export const Link = ({
  src,
  children,
  style,
  ...rest
}: {
  src: string;
  children?: ReactNode;
  style?: StyleInput;
} & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href" | "style">) => (
  <a href={src} style={flatten(style) as React.CSSProperties} {...rest}>
    {children}
  </a>
);

export const Document = ({
  children,
  title,
  style,
}: {
  children?: ReactNode;
  title?: string;
  style?: StyleInput;
}) => (
  <div
    data-pdf-document={title}
    style={
      {
        display: "flex",
        flexDirection: "column",
        ...flatten(style),
      } as React.CSSProperties
    }
  >
    {children}
  </div>
);

export const Page = ({
  children,
  size: _size,
  style,
}: {
  children?: ReactNode;
  size?: string | { width: number; height: number };
  style?: StyleInput;
}) => (
  <div
    data-pdf-page
    style={
      {
        display: "flex",
        flexDirection: "column",
        ...flatten(style),
      } as React.CSSProperties
    }
  >
    {children}
  </div>
);

import type { Template } from "@pdfme/common";
import type { renderToTemplate as RenderToTemplate } from "@pdfme/jsx";

export interface PdfmeTemplateResult {
  template: Template;
  inputs: Record<string, unknown>[];
}

export interface PdfmeDocumentOptions {
  /**
   * Page size preset, e.g. "A4". Defaults to "A4".
   */
  size?: string;
  margin?: { x?: number; y?: number };
}

/**
 * Convert a pdfcn pdfme React preview tree into a pdfme `Template + inputs`
 * pair via `@pdfme/jsx`'s `renderToTemplate`.
 *
 * The element must be built from `@pdfme/jsx` primitives
 * (`Document`, `Page`, `Stack`, `Text`, `Table`, ...), for example via
 * `buildInvoiceClassicJsx()` in the invoice-classic block. See
 * https://pdfme.com/docs/jsx and the JSX playground at
 * https://playground.pdfme.com/jsx for experimentation.
 */
export const renderPdfmeTemplate = async (
  element: Parameters<typeof RenderToTemplate>[0],
  _options?: PdfmeDocumentOptions
): Promise<PdfmeTemplateResult> => {
  const { renderToTemplate } = await import("@pdfme/jsx");
  const { template, inputs } = await renderToTemplate(element);
  return {
    inputs: inputs as Record<string, unknown>[],
    template,
  };
};

/**
 * Build a minimal pdfme `Template` without JSX for environments where the
 * `@pdfme/jsx` runtime is unavailable. Useful as a fallback in tests.
 */
export const buildBlankPdfmeTemplate = (): Template => ({
  basePdf: { height: 297, padding: [18, 16, 18, 16], width: 210 },
  schemas: [
    [
      {
        content: "Invoice",
        fontSize: 24,
        height: 12,
        name: "title",
        position: { x: 16, y: 18 },
        type: "text",
        width: 178,
      },
    ],
  ],
});

import type { Template } from "@pdfme/common";
import { generate } from "@pdfme/generator";

import { getPdfmePlugins } from "@/registry/bases/pdfme/lib/plugins";

/**
 * Generate a PDF buffer from a pdfme `Template + inputs` pair.
 *
 * ```ts
 * import { buildInvoiceClassicJsx } from "@/registry/bases/pdfme/blocks/invoice-classic/invoice-classic.pdfme";
 * import { generatePdfmePdf } from "@/registry/bases/pdfme/lib/generate";
 * import { renderPdfmeTemplate } from "@/registry/bases/pdfme/lib/template";
 *
 * const { template, inputs } = await renderPdfmeTemplate(buildInvoiceClassicJsx());
 * const pdf = await generatePdfmePdf({ template, inputs });
 * ```
 */
export const generatePdfmePdf = async ({
  template,
  inputs,
}: {
  template: Template;
  inputs: Record<string, unknown>[];
}): Promise<Uint8Array> => {
  const pdf = await generate({
    inputs,
    plugins: getPdfmePlugins(),
    template,
  });
  return pdf instanceof Uint8Array ? pdf : new Uint8Array(pdf);
};
